from typing import *

class Solution:
    def totalHammingDistance(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)
        total_distance = 0

        # For each bit position, count how many numbers have that bit set
        # For a given bit position, if c numbers have the bit set, then (n - c) have it unset
        # The contribution to the total Hamming distance from this bit position is c * (n - c)
        for bit in range(32):
            count_set = 0
            for num in nums:
                if (num >> bit) & 1:
                    count_set += 1
            total_distance += count_set * (n - count_set)

        return total_distance
